package mrpapermoon.whisper.service.internalimport com.google.android.gms.nearby.connection.Payloadimport com.google.android.gms.nearby.connection.PayloadTransferUpdateimport mrpapermoon.whisper.utils.asFlowimport java.io.IOExceptioninternal open class StreamPayloadCallback : FlowPayloadCallback() {	@Volatile	private var stream: Payload.Stream? = null	override fun onPayloadReceived(endpointId: String, payload: Payload) {		super.onPayloadReceived(endpointId, payload)		when (payload.type) {			Payload.Type.STREAM -> {				stream = payload.asStream()			}			else -> {				emitEvent(Event.OnUnsupportedPayloadReceived())			}		}	}	override fun onPayloadTransferUpdate(endpointId: String, update: PayloadTransferUpdate) {		super.onPayloadTransferUpdate(endpointId, update)		// TODO: фильтровать исходящие		val stream = stream		if (stream == null) {			logger.error { "Stream is null" }			emitEvent(Event.OnUnsupportedPayloadReceived())			return		}		when (update.status) {			PayloadTransferUpdate.Status.IN_PROGRESS -> {				logger.debug { "Stream in progress(bytesTransferred: ${update.bytesTransferred}, totalBytes:${update.totalBytes})" }			}			PayloadTransferUpdate.Status.SUCCESS -> {				val byteFlow = stream.asInputStream().asFlow {					if (it is IOException) {						logger.error(it) { "Error reading stream" }						emitEvent(Event.OnUnsupportedPayloadReceived())					} else {						throw it					}				}				emitEvent(Event.OnStreamPayloadReceived(byteFlow))			}		}	}}